CREATE TABLE [A] (
  [id] integer,
  [code] number
)
GO

CREATE TABLE [B] (
  [id] integer,
  [code] number
)
GO

ALTER TABLE [A] ADD FOREIGN KEY ([id]) REFERENCES [B] ([id]) ON DELETE NO ACTION ON UPDATE CASCADE
